import { HttpClient } from './HttpClient.js';
import { AuthManager } from './AuthManager.js';
import { Resource } from './Resource.js';

/**
 * Main Client class for Fluent REST communication.
 */
export class FluentRestClient {
  /**
   * Initializes the client.
   * @param {string} baseUrl - The base URL of the API.
   * @param {object} options - Configuration options (auth, callbacks, retries, logger).
   */
  constructor(baseUrl, options = {}) {
    this.authManager = new AuthManager(options);
    this.httpClient = new HttpClient(baseUrl, this.authManager, options);
  }

  /**
   * Registers a global middleware (interceptor).
   * @param {object} middleware - { request: fn, response: fn }
   */
  use(middleware) {
    this.httpClient.use(middleware);
    return this;
  }

  /**
   * Listens to request telemetry events.
   */
  onRequest(fn) {
    this.httpClient.onRequest(fn);
    return this;
  }

  /**
   * Listens to response telemetry events.
   */
  onResponse(fn) {
    this.httpClient.onResponse(fn);
    return this;
  }

  /**
   * Listens to error telemetry events (e.g. Sentry / Datadog).
   */
  onError(fn) {
    this.httpClient.onError(fn);
    return this;
  }

  /**
   * Clears the in-memory response cache.
   */
  clearCache() {
    this.httpClient.clearCache();
    return this;
  }

  /**
   * Starts a fluent builder for a resource.
   * @param {string} name - The resource name (e.g., 'users').
   */
  resource(name) {
    return new Resource(this.httpClient, name);
  }

  /**
   * Manually refreshes the token.
   */
  async refreshToken() {
    return await this.authManager.refreshToken();
  }
}

export default FluentRestClient;

